"""사용자 auto-generated file 을 id 로 다루기: default 로 지정되지 않은 파일을 만들고, 지우기."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import UTC, datetime
from typing import override

import pytest

from ai.backend.common.dto.manager.v2.auto_generated_file.request import (
    AutoGeneratedFileScopeInput,
    CreateAutoGeneratedFileInput,
    PurgeAutoGeneratedFileInput,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.response import (
    AutoGeneratedFileNode,
    PurgeAutoGeneratedFilePayload,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.types import (
    AutoGeneratedFileScopeType,
)
from ai.backend.manager.api.adapters.auto_generated_file.adapter import AutoGeneratedFileAdapter
from ai.backend.manager.data.permission.types import Permission
from ai.backend.manager.errors.permission import NotEnoughPermission
from ai.backend.manager.errors.storage import DefaultDotfilePurgeForbidden
from ai.backend.manager.models.utils import ExtendedAsyncSAEngine
from ai.backend.testutils.scenario_steps import (
    Answered,
    Given,
    Held,
    Same,
    SameAs,
    Says,
    Scenario,
    Skipped,
    Then,
    Verdict,
    When,
)
from bai_scenario.components.answers import MissingResponse, TheCallIsRefused
from bai_scenario.components.auto_generated_file import (
    A_FILE_NOT_DEFAULT,
    CONFIG_DATA,
    CONFIG_PATH,
    CONFIG_PERMISSION,
    THE_DEFAULT_FILE,
    AUserAndTheirOwnConfig,
    SomeoneWithTheirOwnConfig,
    config_files_left,
)
from bai_scenario.components.domain import WrittenByThisRun
from bai_scenario.runner.acting import ActingAs
from bai_scenario.runner.planting import TestSeedingSession
from bai_scenario.runner.steps import run_scenario

type Laid = AUserAndTheirOwnConfig
type Answer = AutoGeneratedFileNode | PurgeAutoGeneratedFilePayload
type V2Step = Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]


THE_OWNER = Says("파일 주인의 id", english="the owner's id")
GENERATED = Says("데이터베이스가 생성합니다", english="the database generates it")


def seeded(name: str) -> Says:
    return Says(f"심어 둔 {name}의 값", english=f"the {name} seeded")


# --- When ---


@dataclass(frozen=True)
class Creating(When[Laid, AutoGeneratedFileAdapter, Answer]):
    """자기 auto-generated file 하나를 만든다."""

    @override
    def operation(self) -> str:
        return "create"

    @override
    def describe(self, laid: Laid) -> str:
        return Says(
            f"{laid.owner.username}이 자기 {CONFIG_PATH} auto-generated file 을 하나 만듭니다",
            english=f"{laid.owner.username} writes a {CONFIG_PATH} auto-generated file of their own",
        )

    @override
    async def call(self, adapter: AutoGeneratedFileAdapter, laid: Laid) -> Answer:
        with ActingAs(laid.owner):
            payload = await adapter.create(
                CreateAutoGeneratedFileInput(
                    scope=AutoGeneratedFileScopeInput(
                        scope_type=AutoGeneratedFileScopeType.USER, scope_id=laid.owner.id
                    ),
                    path=CONFIG_PATH,
                    permission=CONFIG_PERMISSION,
                    data=CONFIG_DATA,
                )
            )
        return payload.auto_generated_file


@dataclass(frozen=True)
class Purging(When[Laid, AutoGeneratedFileAdapter, Answer]):
    """심은 첫 파일을 지운다."""

    @override
    def operation(self) -> str:
        return "purge"

    @override
    def describe(self, laid: Laid) -> str:
        return Says(
            f"{laid.owner.username}이 자기 {CONFIG_PATH} auto-generated file 을 지웁니다",
            english=f"{laid.owner.username} purges their {CONFIG_PATH} auto-generated file",
        )

    @override
    async def call(self, adapter: AutoGeneratedFileAdapter, laid: Laid) -> Answer:
        with ActingAs(laid.owner):
            return await adapter.purge(PurgeAutoGeneratedFileInput(id=laid.files[0].id))


@dataclass(frozen=True)
class TheNewFileComesBack(Then[Laid, Answer]):
    started: datetime

    @override
    def says(self) -> str:
        return Says(
            "default 로 지정되지 않은 새 파일이 응답으로 옵니다",
            english="the new file, not set as default, comes back",
        )

    @override
    def look(self, laid: Laid, answered: Answered[Answer]) -> list[Verdict]:
        node = answered.response
        if not isinstance(node, AutoGeneratedFileNode):
            return [MissingResponse(answered.raised)]
        return [
            Skipped("id", GENERATED),
            Skipped("entity_id", GENERATED),
            Same("scope_type", str(node.scope_type), str(AutoGeneratedFileScopeType.USER)),
            Held("scope_id", node.scope_id, SameAs(laid.owner.id, THE_OWNER)),
            Same("path", node.path, CONFIG_PATH),
            Same("is_default", node.is_default, False),
            Held("created_at", node.created_at, WrittenByThisRun(self.started)),
            Held("updated_at", node.updated_at, WrittenByThisRun(self.started)),
        ]


@dataclass(frozen=True)
class TheFileIsPurged(Then[Laid, Answer]):
    @override
    def says(self) -> str:
        return Says(
            "지운 파일의 id 가 응답으로 옵니다", english="the id of the file purged comes back"
        )

    @override
    def look(self, laid: Laid, answered: Answered[Answer]) -> list[Verdict]:
        payload = answered.response
        if not isinstance(payload, PurgeAutoGeneratedFilePayload):
            return [MissingResponse(answered.raised)]
        return [
            Held(
                "entity_id",
                payload.entity_id,
                SameAs(laid.files[0].id, seeded(f"{CONFIG_PATH} auto-generated file")),
            )
        ]


@dataclass(frozen=True)
class AUserCreatesAFile(Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]):
    started: datetime

    @override
    def summary(self) -> str:
        return "a-user-granted-create-creates-an-auto-generated-file-not-set-as-default"

    @override
    def describe(self) -> str:
        return Says(
            "자기 auto-generated file 에 CREATE 를 받은 사용자가 auto-generated file 을 만들면, "
            "그 파일은 default 로 지정되지 않은 채 응답으로 오고 내용은 revision 1 로 남습니다",
            english=(
                "when a user holding CREATE on their own auto-generated files creates one, the "
                "file comes back not set as default, and its content stays as revision 1"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(permissions=(Permission.CREATE,))

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return Creating()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheNewFileComesBack(started=self.started)


@dataclass(frozen=True)
class AUserGrantedNothingMayNotCreate(
    Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]
):
    @override
    def summary(self) -> str:
        return "a-user-granted-nothing-may-not-create-an-auto-generated-file"

    @override
    def describe(self) -> str:
        return Says(
            "권한을 받지 않은 사용자가 자기 auto-generated file 을 만들려 하면, 권한 부족으로 "
            "거부됩니다",
            english=(
                "a user holding no permission who tries to create their own auto-generated file "
                "is rejected for lack of permission"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig()

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return Creating()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheCallIsRefused(NotEnoughPermission)


@dataclass(frozen=True)
class AUserPurgesAFile(Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]):
    @override
    def summary(self) -> str:
        return "a-user-granted-hard-delete-purges-an-auto-generated-file-not-set-as-default"

    @override
    def describe(self) -> str:
        return Says(
            "HARD_DELETE 를 받은 사용자가 default 로 지정되지 않은 자기 auto-generated file 을 "
            "지우면, 지운 파일의 id 가 오고 파일과 그 revision 이 모두 지워집니다",
            english=(
                "when a user holding HARD_DELETE purges their auto-generated file not set as "
                "default, the id of the file comes back and the file and its revisions are gone"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(
            permissions=(Permission.HARD_DELETE,), files=(A_FILE_NOT_DEFAULT,)
        )

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return Purging()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheFileIsPurged()


@dataclass(frozen=True)
class AUserGrantedNothingMayNotPurge(
    Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]
):
    @override
    def summary(self) -> str:
        return "a-user-granted-nothing-may-not-purge-an-auto-generated-file"

    @override
    def describe(self) -> str:
        return Says(
            "권한을 받지 않은 사용자가 자기 auto-generated file 을 지우려 하면, 권한 부족으로 "
            "거부됩니다",
            english=(
                "a user holding no permission who tries to purge their auto-generated file is "
                "rejected for lack of permission"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(files=(A_FILE_NOT_DEFAULT,))

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return Purging()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheCallIsRefused(NotEnoughPermission)


@dataclass(frozen=True)
class TheDefaultFileMayNotBePurged(
    Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]
):
    @override
    def summary(self) -> str:
        return "purging-the-auto-generated-file-set-as-default-is-refused"

    @override
    def describe(self) -> str:
        return Says(
            "HARD_DELETE 를 받은 사용자가 default 로 지정된 자기 auto-generated file 을 지우려 하면, "
            "거부되고 그 파일은 그대로 남습니다",
            english=(
                "when a user holding HARD_DELETE tries to purge their auto-generated file set as "
                "default, it is rejected and the file stays"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(
            permissions=(Permission.HARD_DELETE,), files=(THE_DEFAULT_FILE,)
        )

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return Purging()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheCallIsRefused(DefaultDotfilePurgeForbidden)


SCENARIOS: list[V2Step] = [
    AUserCreatesAFile(started=datetime.now(UTC)),
    AUserGrantedNothingMayNotCreate(),
    AUserPurgesAFile(),
    AUserGrantedNothingMayNotPurge(),
    TheDefaultFileMayNotBePurged(),
]


@pytest.mark.parametrize("scenario", SCENARIOS, ids=lambda s: s.summary())
async def test_v2_files(
    scenario: V2Step,
    auto_generated_file_adapter: AutoGeneratedFileAdapter,
    engine: ExtendedAsyncSAEngine,
) -> None:
    await run_scenario(scenario, auto_generated_file_adapter, engine)
    match scenario:
        case AUserCreatesAFile():
            assert await config_files_left(engine) == [
                (CONFIG_PATH, False, [(1, CONFIG_PERMISSION, CONFIG_DATA)])
            ]
        case AUserPurgesAFile():
            assert await config_files_left(engine) == []
        case TheDefaultFileMayNotBePurged():
            assert await config_files_left(engine) == [
                (CONFIG_PATH, True, [(1, CONFIG_PERMISSION, CONFIG_DATA)])
            ]
